import{at as e,it as t,t as n,yt as r}from"./chunks/framework.Br18A9IS.js";var i=JSON.parse(`{"title":"HoloPrograms","description":"","frontmatter":{"title":"HoloPrograms"},"headers":[],"relativePath":"guides/the-manual/testing/holo-programs.md","filePath":"guides/the-manual/testing/holo-programs.md"}`),a={name:`guides/the-manual/testing/holo-programs.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="holoprograms" tabindex="-1">HoloPrograms <a class="header-anchor" href="#holoprograms" aria-label="Permalink to “HoloPrograms”">​</a></h1><div class="danger custom-block"><p class="custom-block-title">Proposed, not implemented</p><p>Nothing on this page ships today. The design is under discussion in <a href="https://github.com/warp-drive-data/warp-drive/pull/11205" target="_blank" rel="noreferrer">the HoloPrograms RFC</a>, and that is the place to comment on it. Everything on the other pages in this section works now.</p></div><p>Today every test states every response it needs, one mock at a time. That is fine for a test about one request and tedious for a test about a screen. A <strong>HoloProgram</strong> is planned to be a named set of simulated API interactions that sets the scene in a single call, so a test can start from a world rather than from a list of payloads.</p><p>A program is planned to be made of three parts:</p><ul><li><strong>Route handlers</strong>, shared across all programs, that answer requests by reading and updating the program&#39;s store.</li><li><strong>A seed</strong>, per program, that sets the store&#39;s starting state for each test.</li><li><strong>Behaviors</strong>, per program and per route, for things a handler should not have to know about, such as a slow endpoint or state that changes between two requests.</li></ul><p>The RFC also proposes <strong>safety protocols</strong>, which are schemas that check mocks match the real API and strip sensitive values before anything is written to disk. It also proposes <strong>VCR style recording</strong>, which records real requests against a real API during development and replays them afterwards.</p><p>Programs are not planned to change replay. A program would run only while recording, and its requests would be written to <code>.mock-cache</code> like any other. The workflow in <a href="./record-and-replay">Recording and replaying</a> stays the layer underneath.</p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};